def run(self, raw_ocr_text, all_visible_text, other_visible_text, output_line, partial_registration_candidate, easyocr_text=None, registration_number='', boat_count=0, boat_detected=False, date_and_time=''):
    import re

    full_re = re.compile(r'(?<![A-Z0-9])([A-Z]{2})[\s-]*([0-9]{3,4})[\s-]*([A-Z]{2})(?![A-Z0-9])', re.I)
    partial_re = re.compile(r'(?<![A-Z0-9])([A-Z]{1,2}[\s-]*[0-9]{3,4}[\s-]*[A-Z]{0,2}|[0-9]{3,4}[\s-]*[A-Z]{1,2})(?![A-Z0-9])', re.I)

    NEGATIVE_PHRASES = [
        'not clearly visible', 'not visible', 'no registration', 'cannot read',
        'unable to read', 'not readable', 'no characters', 'empty string'
    ]

    def flat(v):
        if v is None:
            return []
        if isinstance(v, (list, tuple)):
            out = []
            for x in v:
                out += flat(x)
            return out
        if isinstance(v, dict):
            out = []
            for k in ['parsed_output','result','text','output','raw_output']:
                if k in v:
                    out += flat(v.get(k))
            if out:
                return out
            for x in v.values():
                out += flat(x)
            return out
        s = str(v or '').strip()
        if not s:
            return []
        low = s.lower().strip()
        if low in {'none','null','n/a','na','empty string','""',"''"}:
            return []
        if any(p in low for p in NEGATIVE_PHRASES):
            return []
        return [s]

    def pieces(v):
        out = []
        for t in flat(v):
            # Keep OCR regions separate. Splitting on pipes/newlines prevents distant text from being joined.
            for p in re.split(r'\s*\|\s*|\n+', str(t)):
                p = p.strip()
                if p:
                    out.append(p)
        return out

    def norm(s):
        return re.sub(r'\s+', ' ', str(s or '')).strip(' |,;:-')

    def comp(s):
        return re.sub(r'[^A-Z0-9]', '', str(s or '').upper())

    def add_unique(parts, value):
        value = norm(value)
        key = comp(value)
        if value and key and key not in {comp(p) for p in parts}:
            parts.append(value)
        return parts

    def is_full_registration(value):
        return bool(re.fullmatch(r'[A-Z]{2}[0-9]{3,4}[A-Z]{2}', comp(value)))

    def extract_full_from_piece(text):
        regs = []
        cleaned = re.sub(r'[^A-Z0-9\s-]', ' ', str(text or '').upper())
        cleaned = re.sub(r'\s+', ' ', cleaned).strip()
        for m in full_re.finditer(cleaned):
            candidate = ''.join(m.groups()).upper()
            if candidate not in regs:
                regs.append(candidate)
        # Compact scan only within this single piece, never across multiple OCR pieces.
        c = comp(cleaned)
        for m in re.finditer(r'([A-Z]{2})([0-9]{3,4})([A-Z]{2})', c):
            candidate = ''.join(m.groups()).upper()
            if candidate not in regs:
                regs.append(candidate)
        return regs

    def extract_full(*vals):
        regs = []
        for v in vals:
            for p in pieces(v):
                for r in extract_full_from_piece(p):
                    if r not in regs:
                        regs.append(r)
        return regs

    def extract_partial(*vals, full_regs=None):
        full_regs = full_regs or []
        cands = []
        for v in vals:
            for p in pieces(v):
                cleaned = re.sub(r'[^A-Z0-9\s-]', ' ', p.upper())
                cleaned = re.sub(r'\s+', ' ', cleaned).strip()
                for m in partial_re.finditer(cleaned):
                    cand = norm(m.group(1))
                    cc = comp(cand)
                    if not cc:
                        continue
                    if is_full_registration(cand):
                        continue
                    if any(cc == comp(r) or cc in comp(r) for r in full_regs):
                        continue
                    if re.search(r'[A-Z]', cc) and re.search(r'[0-9]{3,4}', cc):
                        cands.append(cand)
        out = []
        for c in cands:
            if comp(c) not in {comp(x) for x in out}:
                out.append(c)
        return out

    detected_parts = []
    for p in pieces(easyocr_text):
        p = norm(p)
        if not p:
            continue
        if re.search(r'REVEAL|TACTACAM', p, re.I):
            continue
        if re.fullmatch(r'\d{1,2}[/:.-]\d{2}[/:.-]\d{2}', p) or re.search(r'\d{1,2}/\d{1,2}/\d{2,4}', p):
            continue
        add_unique(detected_parts, p)

    # Less strict again: allow focused/parser OCR to confirm full registrations.
    # Safety remains: no prompt example in OCR prompt, negative OCR prose is ignored,
    # and separate text regions are not stitched together.
    full_regs = extract_full(registration_number, raw_ocr_text, detected_parts)
