    partials = [] if final_registration else extract_partial(partial_registration_candidate, raw_ocr_text, registration_number, detected_parts, full_regs=full_regs)
    partial = ', '.join(partials)

    visible_parts = list(detected_parts)
    for candidate in full_regs + partials:
