    all_visible = ' | '.join(visible_parts)

    other_parts = list(visible_parts)
    for reg in full_regs:
        other_parts = [norm(re.sub(r'(?<![A-Z0-9])' + re.escape(reg[0:2]) + r'[\s-]*' + re.escape(reg[2:-2]) + r'[\s-]*' + re.escape(reg[-2:]) + r'(?![A-Z0-9])', ' ', p, flags=re.I)) for p in other_parts]
    other_parts = [p for p in other_parts if p]
    other_visible = ' | '.join(other_parts)

    try:
        count = int(boat_count)
    except Exception:
        count = 0
