    if not detected and (final_registration or partial):
        status = 'registration_text_detected_no_boat'
        line = f'REGISTRATION_TEXT_DETECTED_NO_BOAT | date_and_time={date_and_time} | registration_number={final_registration} | partial_registration_candidate={partial} | boat_count={count} | all_visible_text={all_visible}'
    elif not detected:
        status = 'no_boat'
        line = f'NO_BOAT | date_and_time={date_and_time} | registration_number= | partial_registration_candidate= | boat_count={count} | all_visible_text={all_visible}'
    elif final_registration:
        status = 'detected'
        line = f'DETECTED | date_and_time={date_and_time} | registration_number={final_registration} | partial_registration_candidate= | boat_count={count} | other_visible_text={other_visible}'
    else:
        status = 'undetected'
        line = f'UNDETECTED | date_and_time={date_and_time} | registration_number= | partial_registration_candidate={partial} | boat_count={count} | all_visible_text={all_visible}'

    raw = ' '.join(visible_parts)
    return {'raw_ocr_text': raw, 'all_visible_text': all_visible, 'other_visible_text': other_visible, 'output_line': line, 'partial_registration_candidate': partial, 'registration_number': final_registration, 'status': status}

def run(self, boat_classification):
    import json
    import re

    def first(v):
        if isinstance(v, (list, tuple)):
            return first(v[0]) if v else None
        return v

    def to_dict(v):
        v = first(v)
        if isinstance(v, dict):
            return v
        if v is None:
            return {}
        text = str(v).strip()
        if not text:
            return {}
        text = re.sub(r'^```(?:json)?\s*', '', text, flags=re.I).strip()
        text = re.sub(r'\s*```$', '', text).strip()
        try:
            parsed = json.loads(text)
            if isinstance(parsed, list):
                parsed = first(parsed)
            return parsed if isinstance(parsed, dict) else {}
        except Exception:
            pass
        out = {}
        for key in ['boat_type', 'confidence', 'reason', 'approved_identifiers_found', 'unapproved_observations_report']:
            m = re.search(r'"?' + re.escape(key) + r'"?\s*[:=]\s*(.+?)(?:\n|,\s*"?[a-zA-Z_]+"?\s*[:=]|$)', text, flags=re.I | re.S)
            if m:
                out[key] = m.group(1).strip(' ,"')
        return out

    def stringify(v):
        if v is None:
            return ''
        if isinstance(v, (list, tuple, set)):
            return ' | '.join(str(x).strip() for x in v if str(x).strip())
        if isinstance(v, dict):
            return json.dumps(v, ensure_ascii=False)
        return str(v).strip()

    d = to_dict(boat_classification)
    return {
        'boat_type': stringify(d.get('boat_type', '')),
        'boat_type_identifier_confidence': stringify(d.get('confidence', '')),
        'approved_identifiers_found': stringify(d.get('approved_identifiers_found', '')),
        'unapproved_identifiers': stringify(d.get('unapproved_observations_report', d.get('unapproved_identifiers', ''))),
        'classification_reason': stringify(d.get('reason', '')),
    }

def run(self, registration_number, partial_registration_candidate, raw_ocr_text, all_visible_text, verified_text_region_ocr, focused_registration_ocr):
    import re

    VALID_STATE_PREFIXES = set('AL AK AZ AR CA CO CT DE DC FL GA HI IA ID IL IN KS KY LA MA MD ME MI MN MO MS MT NC ND NE NH NJ NM NV NY OH OK OR PA RI SC SD TN TX UT VA VT WA WI WV WY'.split())
