    NEGATIVE_PHRASES = ['not clearly visible', 'not visible', 'no registration', 'cannot read', 'unable to read', 'not readable', 'no characters', 'empty string', 'not enough visible', 'not fully visible', 'not supported']

    def flatten(value):
        if value is None:
            return []
        if isinstance(value, (list, tuple)):
            out = []
            for item in value:
                out.extend(flatten(item))
            return out
        if isinstance(value, dict):
            out = []
            for key in ['parsed_output', 'text', 'result', 'output', 'raw_output']:
                if key in value:
                    out.extend(flatten(value.get(key)))
            if out:
                return out
            for item in value.values():
                out.extend(flatten(item))
            return out
        text = str(value or '').strip()
        if not text:
            return []
        low = text.lower().strip()
        if low in {'none','null','n/a','na','""',"''"}:
            return []
        if any(p in low for p in NEGATIVE_PHRASES):
            return []
        return [text]

