        matches = []
        cleaned = re.sub(r'```.*?```', ' ', str(text or ''), flags=re.S)
        cleaned = re.sub(r'[^A-Z0-9\s\-]', ' ', cleaned.upper())
        cleaned = re.sub(r'\s+', ' ', cleaned).strip()

        for match in spaced_pattern.finditer(cleaned):
            candidate = normalize(''.join(match.groups()))
            if is_valid_full_registration(candidate) and candidate not in matches:
                matches.append(candidate)

        if compact_scan_allowed(cleaned, allow_compact):
            compact = normalize(cleaned)
            for match in compact_pattern.finditer(compact):
                candidate = normalize(''.join(match.groups()))
                if is_valid_full_registration(candidate) and candidate not in matches:
                    matches.append(candidate)
        return matches

    def extract_partials_from_piece(text, full_matches):
        partials = []
        cleaned = re.sub(r'[^A-Z0-9\s\-]', ' ', str(text or '').upper())
        cleaned = re.sub(r'\s+', ' ', cleaned).strip()
        for match in partial_pattern.finditer(cleaned):
            candidate = re.sub(r'\s+', ' ', match.group(1)).strip()
            compact = normalize(candidate)
            if not compact:
                continue
            if is_valid_full_registration(compact):
                continue
            if any(compact == normalize(full) or compact in normalize(full) for full in full_matches):
                continue
            letters = re.sub(r'[^A-Z]', '', compact)
            digits = re.sub(r'[^0-9]', '', compact)
            if 3 <= len(digits) <= 4 and 1 <= len(letters) <= 4:
                partials.append(candidate)
        return partials

    weighted_sources = [
        ('verified_text_region_ocr', verified_text_region_ocr, 120, False),
        ('all_visible_text', all_visible_text, 60, False),
        ('focused_registration_ocr', focused_registration_ocr, 110, True),
        ('registration_number', registration_number, 90, True),
        ('raw_ocr_text', raw_ocr_text, 70, True),
        ('partial_registration_candidate', partial_registration_candidate, 35, False),
    ]

    candidate_scores = {}
    candidate_first_seen = {}
    occurrence_index = 0
    all_source_pieces = []

    for source_name, source_value, source_weight, allow_compact in weighted_sources:
        for piece in pieces(source_value):
            all_source_pieces.append(piece)
            for candidate in extract_full_matches_from_piece(piece, allow_compact=allow_compact):
                occurrence_index += 1
                if candidate not in candidate_scores:
                    candidate_scores[candidate] = {'score': 0, 'source_count': 0, 'best_weight': 0, 'sources': set()}
                    candidate_first_seen[candidate] = occurrence_index
                candidate_scores[candidate]['score'] += source_weight
                candidate_scores[candidate]['source_count'] += 1
                candidate_scores[candidate]['best_weight'] = max(candidate_scores[candidate]['best_weight'], source_weight)
                candidate_scores[candidate]['sources'].add(source_name)

    grouped = {}
    for candidate in candidate_scores:
        core = digit_core(candidate)
        if core:
            grouped.setdefault(core, []).append(candidate)

    matches = []
    for core, candidates in grouped.items():
        def rank(candidate):
            stats = candidate_scores[candidate]
            return (stats['score'], stats['source_count'], stats['best_weight'], -candidate_first_seen.get(candidate, 999999))
        best = sorted(candidates, key=rank, reverse=True)[0]
        if best not in matches:
            matches.append(best)

    cleaned_partials = []
    for piece in all_source_pieces:
        for candidate in extract_partials_from_piece(piece, matches):
            key = normalize(candidate)
            if key and key not in {normalize(v) for v in cleaned_partials}:
                cleaned_partials.append(candidate)

    confirmed_cores = {digit_core(m) for m in matches if digit_core(m)}
    filtered_partials = []
    for candidate in cleaned_partials:
        key = normalize(candidate)
        candidate_core = digit_core(candidate)
        if candidate_core and candidate_core in confirmed_cores:
            continue
        if key not in {normalize(v) for v in filtered_partials}:
            filtered_partials.append(candidate)

    matched_pattern = ''
    if matches:
        if any(re.fullmatch(r'[A-Z]{2}[0-9]{3}[A-Z]{2}', m) for m in matches):
            matched_pattern = 'LLNNNLL'
        if any(re.fullmatch(r'[A-Z]{2}[0-9]{4}[A-Z]{2}', m) for m in matches):
            matched_pattern = 'LLNNNNLL' if not matched_pattern else matched_pattern + ', LLNNNNLL'

    return {'registration_number': ', '.join(matches), 'partial_registration_candidate': ', '.join(filtered_partials), 'matched_pattern': matched_pattern}

def run(self, boat_detected, boat_count, date_and_time, registration_number, partial_registration_candidate, all_visible_text, other_visible_text):
    def clean(v):
        return str(v or '').strip()
    try:
        count = int(boat_count)
    except Exception:
        count = 0
    detected = bool(boat_detected) or count > 0
    date_and_time = clean(date_and_time)
    registration_number = clean(registration_number)
    partial_registration_candidate = clean(partial_registration_candidate)
    all_visible_text = clean(all_visible_text)
    other_visible_text = clean(other_visible_text)
    if not detected and (registration_number or partial_registration_candidate):
        status = 'registration_text_detected_no_boat'
        line = f'REGISTRATION_TEXT_DETECTED_NO_BOAT | date_and_time={date_and_time} | registration_number={registration_number} | partial_registration_candidate={partial_registration_candidate} | boat_count={count} | all_visible_text={all_visible_text}'
    elif not detected:
        status = 'no_boat'
        line = f'NO_BOAT | date_and_time={date_and_time} | registration_number= | partial_registration_candidate= | boat_count={count} | all_visible_text={all_visible_text}'
    elif registration_number:
        status = 'detected'
        line = f'DETECTED | date_and_time={date_and_time} | registration_number={registration_number} | partial_registration_candidate={partial_registration_candidate} | boat_count={count} | other_visible_text={other_visible_text}'
    else:
        status = 'undetected'
        line = f'UNDETECTED | date_and_time={date_and_time} | registration_number= | partial_registration_candidate={partial_registration_candidate} | boat_count={count} | all_visible_text={all_visible_text}'
    return {'status': status, 'output_line': line}

def run(self, reconstruction_output, confirmed_registration, partial_registration_candidate, raw_ocr_text, all_visible_text):
    import json, re

    VALID_STATE_PREFIXES = set('AL AK AZ AR CA CO CT DE DC FL GA HI IA ID IL IN KS KY LA MA MD ME MI MN MO MS MT NC ND NE NH NJ NM NV NY OH OK OR PA RI SC SD TN TX UT VA VT WA WI WV WY'.split())

    def flatten(v):
        if v is None:
            return []
        if isinstance(v, (list, tuple)):
            out = []
            for x in v:
                out.extend(flatten(x))
            return out
        if isinstance(v, dict):
            return [v]
        s = str(v or '').strip()
        return [s] if s else []

    def first_dict(v):
        for item in flatten(v):
            if isinstance(item, dict):
                return item
            text = str(item).strip()
            text = re.sub(r'^```(?:json)?\s*', '', text, flags=re.I).strip()
            text = re.sub(r'\s*```$', '', text).strip()
            try:
                parsed = json.loads(text)
                if isinstance(parsed, list) and parsed:
                    parsed = parsed[0]
                if isinstance(parsed, dict):
                    return parsed
            except Exception:
                continue
        return {}

    def compact(v):
        return re.sub(r'[^A-Z0-9]', '', str(v or '').upper())

    def digit_core(v):
        m = re.search(r'([0-9]{3,4})', compact(v))
        return m.group(1) if m else ''

    def is_valid_full(v):
        c = compact(v)
        return bool(re.fullmatch(r'[A-Z]{2}[0-9]{3,4}[A-Z]{2}', c)) and c[:2] in VALID_STATE_PREFIXES

    def to_float(v):
        try:
            return float(v)
        except Exception:
            m = re.search(r'0?\.\d+|1(?:\.0+)?|\d+', str(v or ''))
            return float(m.group(0)) if m else 0.0

    def text_pool(*vals):
        parts = []
        for v in vals:
            parts.extend(str(x) for x in flatten(v) if not isinstance(x, dict))
        return ' | '.join(parts)

    confirmed = compact(confirmed_registration)
    partial_text = text_pool(partial_registration_candidate, raw_ocr_text, all_visible_text)
    partial_core = digit_core(partial_text)
    d = first_dict(reconstruction_output)

    raw_candidate = d.get('registration_reconstruction_candidate') or d.get('reconstruction_candidate') or d.get('candidate') or d.get('registration_number') or ''
    candidate = compact(raw_candidate)
    confidence = to_float(d.get('confidence', d.get('registration_reconstruction_confidence', 0)))
    reason = str(d.get('reason', d.get('registration_reconstruction_reason', '')) or '').strip()

    if confirmed:
        return {
            'registration_reconstruction_candidate': '',
            'registration_reconstruction_confidence': '',
            'registration_reconstruction_reason': 'confirmed registration already available; reconstruction not needed',
            'registration_reconstruction_review_needed': False,
            'registration_reconstruction_status': 'not_needed'
        }

    if not candidate:
        return {
            'registration_reconstruction_candidate': '',
            'registration_reconstruction_confidence': '',
            'registration_reconstruction_reason': reason,
            'registration_reconstruction_review_needed': bool(partial_text.strip()),
            'registration_reconstruction_status': 'no_candidate'
        }

    valid = is_valid_full(candidate)
    core_matches = bool(partial_core and digit_core(candidate) == partial_core)
    suffix = candidate[-2:]
    prefix = candidate[:2]
    pool_compact = compact(partial_text)
    suffix_supported = suffix in pool_compact
    prefix_partially_supported = any(ch in pool_compact for ch in prefix)
    high_confidence = confidence >= 0.80

    if valid and core_matches and suffix_supported and prefix_partially_supported and high_confidence:
        status = 'review_candidate'
        review_needed = True
        out_candidate = candidate
    else:
        status = 'rejected_candidate'
        review_needed = bool(partial_text.strip())
        out_candidate = ''
        checks = []
        if not valid: checks.append('invalid full registration format or state prefix')
        if not core_matches: checks.append('numeric core not supported by partial OCR')
        if not suffix_supported: checks.append('suffix not supported by visible text')
        if not prefix_partially_supported: checks.append('prefix not supported by visible text')
        if not high_confidence: checks.append('confidence below threshold')
        if checks:
            reason = (reason + ' | ' if reason else '') + '; '.join(checks)

    return {
        'registration_reconstruction_candidate': out_candidate,
        'registration_reconstruction_confidence': f'{confidence:.2f}' if confidence else '',
        'registration_reconstruction_reason': reason,
        'registration_reconstruction_review_needed': review_needed,
        'registration_reconstruction_status': status
    }

def run(self, registration_number, partial_registration_candidate):
    def clean(value):
        if value is None:
            return ''
        if isinstance(value, (list, tuple)):
            for item in value:
                cleaned = clean(item)
                if cleaned:
                    return cleaned
            return ''
        if isinstance(value, dict):
            for key in ['registration_number', 'partial_registration_candidate', 'candidate', 'output', 'result', 'text']:
                if key in value:
                    cleaned = clean(value.get(key))
                    if cleaned:
                        return cleaned
            return ''
        text = str(value).strip()
        if text.lower() in {'none', 'null', 'n/a', 'na', '""', "''"}:
            return ''
        return text

    confirmed = clean(registration_number)
    partial = clean(partial_registration_candidate)
    return {'candidate': confirmed or partial}
